{
  "name": "provider-studio",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "GUI to add custom AI providers & models to opencode, Kilo Code, Cline, Roo Code and other harnesses.",
  "scripts": {
    "start": "node server.mjs",
    "build": "node build-sea.mjs",
    "verify": "node verify-jsonc.mjs && node verify-paths.mjs && node verify-env.mjs && node verify-schema.mjs && node verify-formats.mjs && node verify-diff.mjs && node verify-rescue.mjs && node verify-catalog.mjs && node verify-batch.mjs && node verify-keypool.mjs && node verify-doctor.mjs && node verify-smart-audit.mjs && node verify-digest.mjs && node verify-harness.mjs && node verify.mjs && node verify-ui.mjs && node verify-sea.mjs",
    "verify:exe": "node build-sea.mjs && node verify-sea.mjs"
  },
  "devDependencies": {
    "esbuild": "^0.28.2",
    "postject": "^1.0.0-alpha.6"
  }
}
